import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
    except StopIteration:
        return

    a = []
    for _ in range(n):
        a.append(int(next(iterator)))

    buckets = [[] for _ in range(n)]
    for idx, val in enumerate(a):
        if val < 0 or val >= n:
            print("Impossible")
            return
        buckets[val].append(idx + 1)

    current_present = 0
    result_order = []

    for k in range(n):
        if not buckets[k]:
            print("Impossible")
            return

        student_idx = buckets[k].pop()
        result_order.append(student_idx)

        if k != current_present:
            needed = current_present - k
            if needed % 3 != 0:
                print("Impossible")
                return
            num_teams = needed // 3
            current_present -= 3 * num_teams

        current_present += 1

    print("Possible")
    print(" ".join(map(str, result_order)))

if __name__ == "__main__":
    solve()
